<template>
 <el-dialog title="审核恢复原计划余量" :visible.sync="visible" width="min(1280px,96vw)" append-to-body :close-on-click-modal="false" :close-on-press-escape="!submitting" :show-close="!submitting" @closed="closed">
  <div v-loading="loading" class="restore-review">
   <p class="muted">{{detail.return_sn}} · 恢复已释放的原计划余量</p>
   <el-alert v-if="error" :title="error" type="error" :closable="false" show-icon/>
   <template v-if="check">
    <el-alert v-if="!error" :title="check.message" :type="check.can_approve?'success':'warning'" :closable="false" show-icon/>
    <div class="summary"><article><span>本次申请恢复</span><strong>{{requiredUnits}}</strong></article><article><span>{{single?'来源及批次可恢复':'原来源额度核对'}}</span><strong>{{recoverableLabel}}</strong></article><article :class="{short:!check.can_approve}"><span>{{single?'本次缺口':'库存不足批次'}}</span><strong>{{shortageLabel}}</strong></article></div>
    <el-alert v-if="check.inventory_error" :title="check.inventory_error" type="warning" :closable="false"/>
    <article v-for="l in check.lines" :key="l.id" class="source-card">
     <header><div><b>{{l.goods_name}}</b><div class="muted">{{l.sku_sn}} · {{l.batch_code}} · {{l.inventory_type==='ZP'?'正品':'次品'}}</div><div class="muted">原入库 {{l.ticket_sn}} · {{l.source_key}}</div></div><el-tag size="small" :type="l.source_shortage_quantity?'warning':'success'">{{l.source_shortage_quantity?'原来源额度不足':'原来源额度满足'}}</el-tag></header>
     <div class="source-numbers"><div><span>原来源实收</span><b>{{l.source_quantity}} {{l.stock_unit}}</b></div><div><span>本单已退</span><b>{{l.own_posted_quantity}} {{l.stock_unit}}</b></div><div><span>其他退仓已用 / 占用</span><b>{{l.other_claimed_quantity}} {{l.stock_unit}}</b></div><div><span>原来源余额</span><b>{{l.source_available_quantity}} {{l.stock_unit}}</b></div><div><span>本次需恢复</span><b>{{l.required_quantity}} {{l.stock_unit}}</b></div><div :class="{short:l.source_shortage_quantity}"><span>原来源缺口</span><b>{{l.source_shortage_quantity}} {{l.stock_unit}}</b></div></div>
     <p class="muted">原来源余额：{{l.source_quantity}} − {{l.own_posted_quantity}} − {{l.other_claimed_quantity}} = {{l.source_available_quantity}} {{l.stock_unit}}。原批次当前可用：{{l.inventory_known?l.batch_available_quantity+' '+l.stock_unit:'尚未确认'}}。</p>
     <h4>占用同一原入库来源的其他退仓</h4>
     <el-table :data="l.claimants" size="small" empty-text="没有其他退仓使用该原入库来源"><el-table-column label="退仓单号" min-width="300"><template slot-scope="{row}"><router-link :to="returnLink(row.return_id)" target="_blank" rel="noopener">{{row.return_sn}}</router-link></template></el-table-column><el-table-column label="当前进度" min-width="150"><template slot-scope="{row}">{{stateLabel(row)}}</template></el-table-column><el-table-column label="来源已用 / 计划占用" min-width="150"><template slot-scope="{row}">{{row.claimed_quantity}} {{l.stock_unit}}</template></el-table-column><el-table-column label="实出已扣 / 未出计划" min-width="170"><template slot-scope="{row}">{{row.posted_quantity}} / {{row.unexecuted_claim_quantity}} {{l.stock_unit}}</template></el-table-column><el-table-column label="操作" width="120"><template slot-scope="{row}"><router-link :to="returnLink(row.return_id)" target="_blank" rel="noopener">查看并处理</router-link></template></el-table-column></el-table>
    </article>
    <template v-if="check.inventory_groups.length"><h4>原批次库存核对</h4><el-table :data="check.inventory_groups" size="small"><el-table-column label="SKU / 批次 / 质量" min-width="300"><template slot-scope="{row}">{{row.sku_sn}}<div class="muted">{{row.batch_code}} · {{row.inventory_type==='ZP'?'正品':'次品'}}</div></template></el-table-column><el-table-column label="本次合计恢复"><template slot-scope="{row}">{{row.required_quantity}} {{row.stock_unit}}</template></el-table-column><el-table-column label="批次当前可用"><template slot-scope="{row}">{{row.inventory_known?row.available_quantity+' '+row.stock_unit:'尚未确认'}}</template></el-table-column><el-table-column label="批次缺口"><template slot-scope="{row}"><span :class="{short:row.shortage_quantity}">{{row.inventory_known?row.shortage_quantity+' '+row.stock_unit:'尚未确认'}}</span></template></el-table-column></el-table></template>
    <div class="guidance"><b>后续处理</b><p v-if="!check.source_ok">如优先恢复本单，请先查看仍有未出计划的占用单据，协调停止其剩余退仓；等仓库确认停止及库存释放后，返回此处刷新核对。已经实际出库的数量仍计入原来源已用额度。</p><p v-else-if="!check.inventory_ok">原来源额度满足时，仍需核对原批次库存。可先查看同采购退仓的占用情况，或核实当前批次的可用余额，再刷新核对。</p><p v-else>核对通过后可审核恢复。系统将重新校验并锁定原批次库存，再在同一CGT下追加仓库执行。</p><p class="muted">本次恢复按原申请的完整余量执行。当前余额用于核对，审核和库存锁定时还会再次检查来源、订单预占及可用库存。</p><router-link :to="{path:'/oms-supplychain/purchaseReturns',query:{po_sn:check.po_sn}}" target="_blank" rel="noopener">查看同采购全部退仓</router-link><span v-if="check.claimants_truncated" class="muted"> · 此处最多展示200条占用明细，更多单据请到同采购退仓列表查询</span></div>
    <p class="muted">最近核对：{{String(check.checked_at||'').replace('T',' ')}}</p>
   </template>
  </div>
  <span slot="footer"><el-button :disabled="submitting" @click="visible=false">返回</el-button><el-button :loading="loading" :disabled="submitting" @click="refresh()">刷新额度与库存</el-button><el-button type="primary" :loading="submitting" :disabled="loading||!check||!check.can_approve" v-hasPermi="['warehouse:purchaseReturn:restoreApprove']" @click="approve">审核并恢复原计划余量</el-button></span>
 </el-dialog>
</template>
<script>
import {checkReturnRestore,approveReturnRestore} from '@/api/purchase/returns'
export default {
 props:{detail:{type:Object,required:true}},data:()=>({visible:false,loading:false,submitting:false,requestId:null,check:null,error:'',sequence:0}),
 computed:{single(){return this.check&&this.check.lines.length===1?this.check.lines[0]:null},requiredUnits(){const totals={};for(const l of this.check&&this.check.lines||[])totals[l.stock_unit]=(totals[l.stock_unit]||0)+Number(l.required_quantity);return Object.keys(totals).map(k=>totals[k]+' '+k).join(' + ')||'0'},recoverableLabel(){if(!this.single)return this.check&&this.check.source_ok?'满足':'不满足';if(!this.single.inventory_known)return '库存待确认';return Math.min(Number(this.single.required_quantity),Number(this.single.source_available_quantity),Number(this.single.batch_available_quantity))+' '+this.single.stock_unit},shortageLabel(){if(this.single){if(!this.single.inventory_known)return '库存待确认';return Math.max(0,Number(this.single.required_quantity)-Math.min(Number(this.single.source_available_quantity),Number(this.single.batch_available_quantity)))+' '+this.single.stock_unit}return (this.check&&this.check.inventory_groups||[]).filter(g=>!g.inventory_known||Number(g.shortage_quantity)>0).length+' 组'}},
 watch:{'detail.id'(){this.visible=false;this.closed()}},beforeDestroy(){this.sequence++},
 methods:{returnLink(id){return {path:'/oms-supplychain/purchaseReturns',query:{id}}},stateLabel(row){if(row.state==='CANCELED')return '剩余已停止，保留已出库';if(row.state==='COMPLETED')return '原计划已出库';if(row.state==='APPROVING')return '库存锁定待确认';if(row.state==='CANCELING')return '停止剩余待仓库确认';return ({ACCEPTED:'仓库已受理，等待出库',FAILED:'下发失败',UNKNOWN:'仓库结果待确认',SENDING:'下发结果待确认',PENDING:'等待下发',VIRTUAL:'自动虚拟执行'})[row.dispatch_state]||'退仓处理中'},open(request){if(this.submitting||this.visible&&this.requestId===request.id)return;this.requestId=request.id;this.check=null;this.error='';this.visible=true;this.refresh()},closed(){this.sequence++;this.loading=false},async refresh(keepError=false){if(this.loading)return;const seq=++this.sequence,parent=this.detail.id,request=this.requestId;this.loading=true;if(!keepError)this.error='';try{const result=(await checkReturnRestore(parent,request)).data;if(seq===this.sequence&&this.visible&&parent===this.detail.id)this.check=result}catch(e){if(seq===this.sequence){this.check=null;this.error=e.message||'恢复额度和库存查询未确认，请刷新核对'}}finally{if(seq===this.sequence)this.loading=false}},async approve(){if(this.submitting||this.loading||!this.check||!this.check.can_approve)return;const parent=this.detail.id,request=this.requestId;this.submitting=true;this.error='';try{await approveReturnRestore(parent,request,{control_version:this.check.control_version});if(parent===this.detail.id){this.visible=false;this.$emit('approved')}}catch(e){if(parent===this.detail.id){this.error=e.message||'恢复审核未确认，请刷新核对原单';if(e.data&&Array.isArray(e.data.lines))this.check={...this.check,...e.data};await this.refresh(true)}}finally{this.submitting=false}}}
}
</script>
<style scoped>
.restore-review{min-height:150px;max-height:67vh;overflow-y:auto;padding:0 5px}.muted{font-size:12px;color:#7b8a9d;line-height:1.8;overflow-wrap:anywhere}.summary{display:grid;grid-template-columns:repeat(3,1fr);gap:14px;margin:20px 0}.summary article{padding:18px;border-radius:8px;background:#f2f7fd}.summary span,.source-numbers span{display:block;color:#7b8a9d;font-size:12px}.summary strong{display:block;font-size:25px;margin-top:10px}.short{color:#bd5c16!important}.source-card{border:1px solid #e0e8f1;border-radius:8px;padding:18px;margin:18px 0}.source-card header{display:flex;align-items:flex-start;justify-content:space-between;gap:16px}.source-card b{font-size:14px}.source-numbers{display:grid;grid-template-columns:repeat(6,1fr);gap:12px;margin-top:22px}.source-numbers b{display:block;margin-top:8px}.guidance{padding:16px;background:#f3f7fc;border-radius:8px;margin-top:20px;line-height:1.8}.guidance p{margin:8px 0}.el-alert{margin:12px 0}a{color:#0877dc;overflow-wrap:anywhere}h4{margin:18px 0 12px}::v-deep .cell{overflow-wrap:anywhere}@media(max-width:900px){.source-numbers{grid-template-columns:repeat(3,1fr)}.summary{gap:8px}.summary article{padding:12px}.summary strong{font-size:20px}}
</style>
